/**
 * Comparing a MAC with `===` leaks where the first byte differs, which is
 * enough to forge one a byte at a time.
 */
function equalsInConstantTime(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// Portable base64 — this package must run in browsers, Node, and RN/Hermes,
// so no Buffer and no reliance on btoa/atob being present.
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64_LOOKUP = new Uint8Array(128).fill(255);
for (let i = 0; i < B64.length; i++) B64_LOOKUP[B64.charCodeAt(i)] = i;

export function bytesToBase64(bytes: Uint8Array): string {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    out += B64[b0 >> 2] + B64[((b0 & 3) << 4) | (b1 >> 4)];
    out += i + 1 < bytes.length ? B64[((b1 & 15) << 2) | (b2 >> 6)] : '=';
    out += i + 2 < bytes.length ? B64[b2 & 63] : '=';
  }
  return out;
}

export function base64ToBytes(base64: string): Uint8Array {
  const clean = base64.replace(/=+$/, '');
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let outIndex = 0;
  let buffer = 0;
  let bits = 0;
  for (let i = 0; i < clean.length; i++) {
    const value = B64_LOOKUP[clean.charCodeAt(i)];
    if (value === 255 || value === undefined) throw new Error('invalid base64');
    buffer = (buffer << 6) | value;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[outIndex++] = (buffer >> bits) & 0xff;
    }
  }
  return out;
}
import { linkParams, setLinkParams } from './linkForm';

/**
 * The connect URL is what the dapp fires as a deeplink (or renders as a QR
 * code). Production shape: https://connect.shield.app/connect#... — a
 * verified universal / app link, so the OS hands it only to the signed Shield
 * app. `shield://connect?...` stays as the legacy custom-scheme form.
 *
 * One rule per URL form, chosen by scheme:
 * - http(s): every param travels in the FRAGMENT. When the app is not
 *   installed the OS loads the page instead, and a query string would send
 *   the bearer pairing `secret` to the web server — access logs, proxies,
 *   analytics. Fragments never leave the browser.
 * - custom scheme: every param travels in the query string. It never reaches
 *   a server.
 * The parser holds each form to its own rule and ignores the other part, so a
 * link cannot be read one way by one client and another way by the next.
 * shield-core's wallet-side parser applies the same rule.
 */

/** Param carrying the bundled first request. See `mayCarryRequest`. */
const INITIAL_MESSAGE_PARAM = 'req';

/**
 * Cap on the decoded bundle. A connect request is a few hundred bytes even
 * with a scoped record-access grant; anything past this is a link trying to
 * make the wallet parse something large before a person has agreed to
 * anything.
 */
export const MAX_INITIAL_MESSAGE_BYTES = 4096;

/**
 * The same cap, measured on the ENCODED value so it can be enforced before
 * anything decodes. The byte cap below is the authoritative one, but by the
 * time it can be applied the link has already had the wallet copy and decode
 * whatever it sent — so a multi-megabyte `req` would be allocated and scanned
 * in full before being rejected, on a phone, before a person has agreed to
 * anything. base64 spends 4 characters per 3 bytes, so this admits every
 * payload the byte cap allows and at most two bytes more.
 */
const MAX_INITIAL_MESSAGE_CHARS = Math.ceil(MAX_INITIAL_MESSAGE_BYTES / 3) * 4;

/**
 * Pairing identity: what the wallet persists, and what the handshake MAC is
 * computed over. Everything here survives a restart and re-authenticates the
 * same pairing.
 *
 * A request bundled into the link is NOT part of this — it is an artifact of
 * the one link a person just acted on, returned alongside by
 * `parseConnectUrl` and never carried on the object `restore()` accepts.
 */
export interface ConnectRequest {
  channelId: string;
  /** Dapp's ECIES public key (hex, compressed). */
  publicKey: string;
  /** Relay websocket URL the wallet should join. */
  relay: string;
  /** Dapp origin for display + session scoping, e.g. https://dapp.example */
  origin: string;
  /**
   * Pairing secret, hex. Minted by the dapp and carried ONLY here — never over
   * the relay — so the wallet's handshake MAC proves its key reached the peer
   * that was shown the QR.
   */
  secret: string;
  version: number;
}

/** A connect URL, as parsed: the pairing, plus the one-shot the link carried. */
